// GnoMoji — Minter Realm
// gno.land/r/g138gdmwj6heduu3st796lw6qqdwylgaxf7ty5gz/minter6
//
// Treasury gateway for GnoMoji on Gno.land (v1.5.0 / Onyx testnet API).
// Called server-side by treasury.server.ts after a player earns coins via ClaimMine.
//
// Security: only the admin (treasury wallet, set at deploy time) can call Mint or MintTool.

package minter6

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
	coinsRealm "gno.land/r/g138gdmwj6heduu3st796lw6qqdwylgaxf7ty5gz/coins"
	gameRealm  "gno.land/r/g138gdmwj6heduu3st796lw6qqdwylgaxf7ty5gz/game11"
)

var (
	admin    address
	mintLogs avl.Tree // addr+":"+coinId → total minted (audit)
)

func init(cur realm) {
	admin = cur.Previous().Address()
}

func isAdmin(cur realm) bool {
	return cur.Previous().Address() == admin
}

// UpdateAdmin transfers the admin role to a new address.
func UpdateAdmin(cur realm, newAdmin string) {
	if !isAdmin(cur) {
		panic("minter: unauthorized")
	}
	admin = address(newAdmin)
}

// AdminAddr returns the current admin address.
func AdminAddr() string {
	return admin.String()
}

// Mint credits coinId tokens to a player address.
// Records in internal audit log and issues real tokens via the coins realm.
func Mint(cur realm, coinId string, toAddr string, amountStr string) {
	if !isAdmin(cur) {
		panic("minter: unauthorized — only treasury can mint")
	}
	if coinId == "" || toAddr == "" {
		panic("minter: coinId and toAddr required")
	}
	if !strings.HasPrefix(toAddr, "g1") {
		panic("minter: invalid Gno.land address")
	}
	amount, err := strconv.ParseUint(amountStr, 10, 64)
	if err != nil || amount == 0 {
		panic("minter: invalid amount")
	}

	// Update audit log
	key := toAddr + ":" + coinId
	existing := uint64(0)
	if mintLogs.Has(key) {
		existing, _ = strconv.ParseUint(mintLogs.Get(key).(string), 10, 64)
	}
	mintLogs.Set(key, strconv.FormatUint(existing+amount, 10))

	// Issue real tokens via the coins realm (cross-realm call)
	coinsRealm.Mint(cross(cur), coinId, toAddr, amountStr)
}

// MintTool records tool ownership for a player on-chain.
func MintTool(cur realm, toolId string, toAddr string, _ string) {
	if !isAdmin(cur) {
		panic("minter: unauthorized — only treasury can mint tools")
	}
	if toolId == "" || toAddr == "" {
		panic("minter: toolId and toAddr required")
	}
	mintLogs.Set(toAddr+":tool:"+toolId, "1")
}

// ClearPendingMints notifies the game realm that coins have been minted.
// Forwards the call to game11.ClearPendingMints to clear the player's pending balance.
func ClearPendingMints(cur realm, playerAddr string, coinsJson string) {
	if !isAdmin(cur) {
		panic("minter: unauthorized")
	}
	if playerAddr == "" {
		return
	}
	gameRealm.ClearPendingMints(cross(cur), playerAddr, coinsJson)
}

// ── Queries ───────────────────────────────────────────────────────────────────

func TotalMinted(playerAddr string, coinId string) string {
	key := playerAddr + ":" + coinId
	if mintLogs.Has(key) {
		return mintLogs.Get(key).(string)
	}
	return "0"
}

func Render(_ string) string {
	return ufmt.Sprintf(
		"# GnoMoji Minter\n\nAdmin: `%s`\n\nPath: `gno.land/r/g138gdmwj6heduu3st796lw6qqdwylgaxf7ty5gz/minter6`\n\nUse Mint(coinId, addr, amount) to credit coins after ClaimMine.\n",
		admin.String(),
	)
}

// Package shoaltoken is the Shoal FISH ledger. Init mints a fixed supply and
// no later call can mint. Wallet Transfer, Approve, and TransferFrom move the
// full amount. BuyTaxBps and SellTaxBps are stored for a later pool realm.
// They do not tax a wallet transfer, a cheer, a season reward, or a community claim.
//
// The symbol is FISH, the same letters as the fish NFT collection. A wallet
// that keys only on the symbol can confuse the two. The chain identity is
// TokenID: the realm path, the symbol, and the sequence.
//
// Deployed on onyx-1 at gno.land/r/g10ragdr3cjqkael8rslpw4y6rlelhev4h0fswcx/shoaltoken.
// Init is a separate call. It does not register this token.
package shoaltoken

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/ownable/v0"
)

const (
	unit            int64 = 1_000_000
	supplyWhole     int64 = 100_000_000
	seasonWhole     int64 = 43_000_000
	liquidityWhole  int64 = 20_000_000
	ecosystemWhole  int64 = 15_000_000
	communityWhole  int64 = 12_000_000
	teamWhole       int64 = 10_000_000
	maxBuyTaxBps    int64 = 500
	maxSellTaxBps   int64 = 1000
	defaultBuyTax   int64 = 200
	defaultSellTax  int64 = 400
)

var (
	token     *grc20.Token
	ledger    *grc20.PrivateLedger
	admin     *ownable.Ownable
	inited    bool
	sealed    bool
	buyTaxBps  int64 = defaultBuyTax
	sellTaxBps int64 = defaultSellTax
)

// Init mints the fixed supply once and seals the ledger. The five treasuries must be distinct.
func Init(cur realm, season, liquidity, ecosystem, community, team address) {
	if !cur.IsCurrent() {
		panic("shoaltoken: realm")
	}
	if !cur.Previous().IsUserCall() {
		panic("shoaltoken: eoa")
	}
	takeExact(0)
	if inited {
		panic("shoaltoken: init")
	}
	if !distinct(season, liquidity, ecosystem, community, team) {
		panic("shoaltoken: addr")
	}
	tok, led := grc20.NewToken("Shoal FISH", "FISH", 6, 0, cur)
	credit(led, season, seasonWhole*unit)
	credit(led, liquidity, liquidityWhole*unit)
	credit(led, ecosystem, ecosystemWhole*unit)
	credit(led, community, communityWhole*unit)
	credit(led, team, teamWhole*unit)
	if tok.TotalSupply() != supplyWhole*unit {
		panic("shoaltoken: supply")
	}
	token = tok
	ledger = led
	admin = ownable.NewWithAddress(cur.Previous().Address())
	inited = true
	sealed = true
	chain.Emit(
		"Init",
		"token", tok.ID(),
		"admin", cur.Previous().Address().String(),
		"supply", strconv.FormatInt(supplyWhole*unit, 10),
	)
}

// Transfer moves FISH from the caller to to. The amount is not taxed.
func Transfer(cur realm, to address, amount int64) {
	requireUser(cur)
	takeExact(0)
	requireReady()
	must(ledger.CallerTeller().Transfer(0, cur, to, amount))
	chain.Emit("Send", "to", to.String(), "amount", strconv.FormatInt(amount, 10))
}

// Approve lets spender move up to amount from the caller. This replaces the previous allowance.
func Approve(cur realm, spender address, amount int64) {
	requireUser(cur)
	takeExact(0)
	requireReady()
	must(ledger.CallerTeller().Approve(0, cur, spender, amount))
	chain.Emit("Approve", "spender", spender.String(), "amount", strconv.FormatInt(amount, 10))
}

// TransferFrom moves amount from owner to to, using the caller's allowance. The amount is not taxed.
func TransferFrom(cur realm, owner, to address, amount int64) {
	requireUser(cur)
	takeExact(0)
	requireReady()
	must(ledger.CallerTeller().TransferFrom(0, cur, owner, to, amount))
	chain.Emit("SendFrom", "owner", owner.String(), "to", to.String(), "amount", strconv.FormatInt(amount, 10))
}

// SetBuyTaxBps stores the buy tax for a later pool. The cap is 500 bps. This does not tax wallets.
func SetBuyTaxBps(cur realm, next int64) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	if !admin.OwnedBy(caller) {
		panic("shoaltoken: admin")
	}
	if next < 0 || next > maxBuyTaxBps {
		panic("shoaltoken: tax")
	}
	buyTaxBps = next
	chain.Emit("SetBuyTaxBps", "bps", strconv.FormatInt(next, 10))
}

// SetSellTaxBps stores the sell tax for a later pool. The cap is 1000 bps. This does not tax wallets.
func SetSellTaxBps(cur realm, next int64) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	if !admin.OwnedBy(caller) {
		panic("shoaltoken: admin")
	}
	if next < 0 || next > maxSellTaxBps {
		panic("shoaltoken: tax")
	}
	sellTaxBps = next
	chain.Emit("SetSellTaxBps", "bps", strconv.FormatInt(next, 10))
}

// TransferAdmin hands the tax hook to next. Balances stay where they are.
func TransferAdmin(cur realm, next address) {
	requireUser(cur)
	takeExact(0)
	requireReady()
	if !next.IsValid() {
		panic("shoaltoken: admin")
	}
	if err := admin.TransferOwnership(0, cur, next); err != nil {
		panic("shoaltoken: admin")
	}
	chain.Emit("TransferAdmin", "next", next.String())
}

func Name() string {
	requireReady()
	return token.GetName()
}

func Symbol() string {
	requireReady()
	return token.GetSymbol()
}

func Decimals() int {
	requireReady()
	return token.GetDecimals()
}

func TotalSupply() int64 {
	requireReady()
	return token.TotalSupply()
}

func BalanceOf(who address) int64 {
	requireReady()
	return token.BalanceOf(who)
}

func Allowance(owner, spender address) int64 {
	requireReady()
	return token.Allowance(owner, spender)
}

func TokenID() string {
	requireReady()
	return token.ID()
}

func BuyTaxBps() int64  { return buyTaxBps }
func SellTaxBps() int64 { return sellTaxBps }
func Version() string   { return "shoaltoken-1" }
func Sealed() bool      { return sealed }

func Admin() address {
	if admin == nil {
		return address("")
	}
	return admin.Owner()
}

func Render(path string) string {
	if path != "" {
		return "# Shoal FISH\n\nUnknown path.\n"
	}
	return "# Shoal FISH\n\nFixed supply. Wallet transfers are not taxed.\n\nThe symbol FISH shares its letters with the fish NFT collection. TokenID is the chain identity.\n"
}

func credit(led *grc20.PrivateLedger, who address, amount int64) {
	if err := led.Mint(who, amount); err != nil {
		panic(err)
	}
}

func must(err error) {
	if err != nil {
		panic(err)
	}
}

func requireReady() {
	if !inited || !sealed || token == nil || ledger == nil || admin == nil {
		panic("shoaltoken: init")
	}
}

func requireUser(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("shoaltoken: eoa")
	}
	return cur.Previous().Address()
}

func takeExact(n int64) {
	sent := unsafe.OriginSend()
	if n == 0 {
		if len(sent) != 0 {
			panic("shoaltoken: payment")
		}
		return
	}
	panic("shoaltoken: payment")
}

func distinct(xs ...address) bool {
	for i, a := range xs {
		if !a.IsValid() {
			return false
		}
		for j := 0; j < i; j++ {
			if xs[j] == a {
				return false
			}
		}
	}
	return true
}

// Package party is the Shoal crew book. Members share a fight and do not
// bite each other. This realm holds no ugnot and no FISH. The fish realm pays a kill.
// Deployed on onyx-1 at gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/shoal/party.
// The older gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/party package stays as it was.
package party

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"
)

const (
	partyCap = 8
	nameMax  = 16
	capFloor = 2
	capCeil  = 32
)

type crew struct {
	id      int
	name    string
	leader  address
	members []address
	closed  bool
}

var (
	crews    []*crew
	seat     map[address]int
	invited  map[address]int
	nextPID  int
	crewCap  = partyCap
	admin    address
	adminSet bool
)

func Create(cur realm, name string) int {
	caller := requireUser(cur)
	takeExact(0)
	if seatOf(caller) != 0 {
		panic("party: seat")
	}
	clean := cleanName(name)
	if clean == "" || taken(clean) {
		panic("party: name")
	}
	ensure()
	nextPID++
	id := nextPID
	body := &crew{
		id:      id,
		name:    clean,
		leader:  caller,
		members: []address{caller},
	}
	for len(crews) <= id {
		crews = append(crews, nil)
	}
	crews[id] = body
	seat[caller] = id
	chain.Emit("Create", "id", strconv.Itoa(id), "leader", caller.String(), "name", clean)
	return id
}

func Invite(cur realm, who address) {
	caller := requireUser(cur)
	takeExact(0)
	if !who.IsValid() {
		panic("party: addr")
	}
	if who == caller {
		panic("party: self")
	}
	id := seatOf(caller)
	body := openCrew(id)
	if seatOf(who) != 0 {
		panic("party: seat")
	}
	if len(body.members) >= crewCap {
		panic("party: full")
	}
	ensure()
	invited[who] = id
	chain.Emit("Invite", "id", strconv.Itoa(id), "who", who.String())
}

func Accept(cur realm) int {
	caller := requireUser(cur)
	takeExact(0)
	if seatOf(caller) != 0 {
		panic("party: seat")
	}
	id := 0
	if invited != nil {
		id = invited[caller]
	}
	body := openCrew(id)
	if len(body.members) >= crewCap {
		panic("party: full")
	}
	delete(invited, caller)
	body.members = append(body.members, caller)
	seat[caller] = id
	chain.Emit("Join", "id", strconv.Itoa(id), "who", caller.String())
	return id
}

func Leave(cur realm) {
	caller := requireUser(cur)
	takeExact(0)
	id := seatOf(caller)
	body := openCrew(id)
	dropMember(body, caller)
	chain.Emit("Leave", "id", strconv.Itoa(id), "who", caller.String())
}

func Kick(cur realm, who address) {
	caller := requireUser(cur)
	takeExact(0)
	id := seatOf(caller)
	body := openCrew(id)
	if body.leader != caller {
		panic("party: leader")
	}
	if who == caller || seatOf(who) != id {
		panic("party: member")
	}
	dropMember(body, who)
	chain.Emit("Kick", "id", strconv.Itoa(id), "who", who.String())
}

func Disband(cur realm) {
	caller := requireUser(cur)
	takeExact(0)
	id := seatOf(caller)
	body := openCrew(id)
	if body.leader != caller {
		panic("party: leader")
	}
	for _, member := range body.members {
		delete(seat, member)
	}
	body.members = nil
	body.closed = true
	body.name = ""
	dropInvites(id)
	chain.Emit("Disband", "id", strconv.Itoa(id))
}

// Cap is the seat limit for a new invite. The default is 8.
func Cap() int { return crewCap }

// Version names this local package shape. The live party realm is unchanged.
func Version() string { return "party-1" }

// Admin is the address that claimed the cap hook. It is empty until ClaimAdmin.
func Admin() address { return admin }

// ClaimAdmin records the first caller. A later caller cannot replace them here.
func ClaimAdmin(cur realm) {
	caller := requireUser(cur)
	takeExact(0)
	if adminSet {
		panic("party: admin")
	}
	admin = caller
	adminSet = true
	chain.Emit("ClaimAdmin", "who", caller.String())
}

// SetCap changes how many seats a crew may fill. Crews that are already larger stay as they are.
func SetCap(cur realm, n int) {
	caller := requireUser(cur)
	takeExact(0)
	if !adminSet || caller != admin {
		panic("party: admin")
	}
	if n < capFloor || n > capCeil {
		panic("party: cap")
	}
	crewCap = n
	chain.Emit("SetCap", "n", strconv.Itoa(n))
}

func PartyOf(cur realm, who address) int {
	takeExact(0)
	return seatOf(who)
}

func SameParty(cur realm, a, b address) bool {
	takeExact(0)
	id := seatOf(a)
	return id != 0 && id == seatOf(b)
}

func NameOf(cur realm, id int) string {
	takeExact(0)
	return openCrew(id).name
}

func LeaderOf(cur realm, id int) address {
	takeExact(0)
	return openCrew(id).leader
}

func MemberCount(cur realm, id int) int {
	takeExact(0)
	return len(openCrew(id).members)
}

func MemberAt(cur realm, id, index int) address {
	takeExact(0)
	body := openCrew(id)
	if index < 0 || index >= len(body.members) {
		panic("party: index")
	}
	return body.members[index]
}

func requireUser(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("party: eoa")
	}
	return cur.Previous().Address()
}

func takeExact(n int64) {
	sent := unsafe.OriginSend()
	if n == 0 {
		if len(sent) != 0 {
			panic("party: payment")
		}
		return
	}
	panic("party: payment")
}

func ensure() {
	if seat == nil {
		seat = make(map[address]int)
	}
	if invited == nil {
		invited = make(map[address]int)
	}
}

func seatOf(who address) int {
	if seat == nil || !who.IsValid() {
		return 0
	}
	return seat[who]
}

func openCrew(id int) *crew {
	if id < 1 || id >= len(crews) || crews[id] == nil || crews[id].closed {
		panic("party: none")
	}
	return crews[id]
}

func taken(name string) bool {
	for _, body := range crews {
		if body != nil && !body.closed && body.name == name {
			return true
		}
	}
	return false
}

func cleanName(name string) string {
	if len(name) < 1 || len(name) > nameMax {
		return ""
	}
	for _, c := range name {
		if (c < 'a' || c > 'z') && (c < 'A' || c > 'Z') && (c < '0' || c > '9') && c != ' ' {
			return ""
		}
	}
	return name
}

func dropMember(body *crew, who address) {
	next := make([]address, 0, len(body.members))
	for _, member := range body.members {
		if member != who {
			next = append(next, member)
		}
	}
	delete(seat, who)
	if invited != nil {
		delete(invited, who)
	}
	if len(next) == 0 {
		body.members = nil
		body.closed = true
		body.name = ""
		dropInvites(body.id)
		return
	}
	body.members = next
	body.leader = next[0]
}

func dropInvites(id int) {
	if invited == nil {
		return
	}
	var drop []address
	for who, pid := range invited {
		if pid == id {
			drop = append(drop, who)
		}
	}
	for _, who := range drop {
		delete(invited, who)
	}
}

// Package profile is the Shoal sailor card. One address has one username.
// This realm holds no ugnot. It does not mint FISH and it does not mint a fish NFT.
// Deployed on onyx-1 at gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/shoal/profile.
// The older profile package at the founder root stays as it was.
package profile

import (
	"chain"
	"chain/runtime/unsafe"
)

type card struct {
	username string
	country  string
	crest    string
}

var (
	byAddr       map[address]*card
	byName       map[string]address
	admin        address
	adminSet     bool
	extraCountry map[string]bool
	extraCrest   map[string]bool
)

// SetProfile stores this caller's sailor card. The caller does not need a fish NFT.
// A later fact is a new function. This one keeps username, country, and crest.
func SetProfile(cur realm, username, country, crest string) {
	caller := requireUser(cur)
	takeExact(0)
	name := cleanUser(username)
	if name == "" {
		panic("profile: name")
	}
	if !knownCountry(country) {
		panic("profile: country")
	}
	if !knownCrest(crest) {
		panic("profile: crest")
	}
	ensure()
	if owner, ok := byName[name]; ok && owner != caller {
		panic("profile: taken")
	}
	prev := byAddr[caller]
	if prev != nil && prev.username == name && prev.country == country && prev.crest == crest {
		return
	}
	if prev != nil && prev.username != name {
		delete(byName, prev.username)
	}
	byAddr[caller] = &card{username: name, country: country, crest: crest}
	byName[name] = caller
	chain.Emit("SetProfile", "who", caller.String(), "username", name, "country", country, "crest", crest)
}

// Version names this local package shape. The live profile realm is unchanged.
func Version() string { return "profile-1" }

// Admin is empty until ClaimAdmin. SetProfile does not claim it.
func Admin() address { return admin }

// ClaimAdmin records the first caller. A later caller cannot replace them here.
func ClaimAdmin(cur realm) {
	caller := requireUser(cur)
	takeExact(0)
	if adminSet {
		panic("profile: admin")
	}
	admin = caller
	adminSet = true
	chain.Emit("ClaimAdmin", "who", caller.String())
}

// AddCountry lets the admin accept one more country name. Built-in names stay.
func AddCountry(cur realm, name string) {
	caller := requireUser(cur)
	takeExact(0)
	if !adminSet || caller != admin {
		panic("profile: admin")
	}
	if !placeName(name) || knownCountry(name) {
		panic("profile: country")
	}
	if extraCountry == nil {
		extraCountry = make(map[string]bool)
	}
	extraCountry[name] = true
	chain.Emit("AddCountry", "name", name)
}

// AddCrest lets the admin accept one more crest name. Built-in names stay.
func AddCrest(cur realm, name string) {
	caller := requireUser(cur)
	takeExact(0)
	if !adminSet || caller != admin {
		panic("profile: admin")
	}
	if !placeName(name) || knownCrest(name) {
		panic("profile: crest")
	}
	if extraCrest == nil {
		extraCrest = make(map[string]bool)
	}
	extraCrest[name] = true
	chain.Emit("AddCrest", "name", name)
}

func Has(cur realm, who address) bool {
	takeExact(0)
	return cardOf(who) != nil
}

func UsernameOf(cur realm, who address) string {
	takeExact(0)
	body := cardOf(who)
	if body == nil {
		return ""
	}
	return body.username
}

func CountryOf(cur realm, who address) string {
	takeExact(0)
	body := cardOf(who)
	if body == nil {
		return ""
	}
	return body.country
}

func CrestOf(cur realm, who address) string {
	takeExact(0)
	body := cardOf(who)
	if body == nil {
		return ""
	}
	return body.crest
}

func AddressOf(cur realm, username string) address {
	takeExact(0)
	name := cleanUser(username)
	if name == "" || byName == nil {
		return address("")
	}
	return byName[name]
}

func requireUser(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("profile: eoa")
	}
	return cur.Previous().Address()
}

func takeExact(n int64) {
	sent := unsafe.OriginSend()
	if n == 0 {
		if len(sent) != 0 {
			panic("profile: payment")
		}
		return
	}
	panic("profile: payment")
}

func ensure() {
	if byAddr == nil {
		byAddr = make(map[address]*card)
	}
	if byName == nil {
		byName = make(map[string]address)
	}
}

func cardOf(who address) *card {
	if byAddr == nil || !who.IsValid() {
		return nil
	}
	return byAddr[who]
}

func cleanUser(name string) string {
	for len(name) > 0 && name[0] == ' ' {
		name = name[1:]
	}
	for len(name) > 0 && name[len(name)-1] == ' ' {
		name = name[:len(name)-1]
	}
	if len(name) < 3 || len(name) > 16 {
		return ""
	}
	out := ""
	for _, c := range name {
		if c >= 'A' && c <= 'Z' {
			c = c - 'A' + 'a'
		}
		if (c < 'a' || c > 'z') && (c < '0' || c > '9') {
			return ""
		}
		out += string(c)
	}
	return out
}

func knownCountry(s string) bool {
	switch s {
	case "Sea", "Vietnam", "Korea", "Japan", "Brazil", "France", "Nigeria", "Canada", "Australia":
		return true
	}
	return extraCountry != nil && extraCountry[s]
}

func knownCrest(s string) bool {
	switch s {
	case "wave", "reef", "moon", "sun", "fang", "shell":
		return true
	}
	return extraCrest != nil && extraCrest[s]
}

func placeName(s string) bool {
	if len(s) < 2 || len(s) > 24 {
		return false
	}
	for _, c := range s {
		if (c < 'a' || c > 'z') && (c < 'A' || c > 'Z') {
			return false
		}
	}
	return true
}

// Package shoaltoken is the Shoal FISH ledger. Init mints a fixed supply and
// no later call can mint. Wallet Transfer, Approve, and TransferFrom move the
// full amount. BuyTaxBps and SellTaxBps are stored for a later pool realm.
// They do not tax a wallet transfer, a cheer, a season reward, or a community claim.
//
// The symbol is FISH, the same letters as the fish NFT collection. A wallet
// that keys only on the symbol can confuse the two. The chain identity is
// TokenID: the realm path, the symbol, and the sequence.
//
// Deployed on onyx-1 at gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/shoal/shoaltoken.
// An earlier copy remains at gno.land/r/g10ragdr3cjqkael8rslpw4y6rlelhev4h0fswcx/shoaltoken.
// Init is a separate call. It does not register this token.
package shoaltoken

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/ownable/v0"
)

const (
	unit            int64 = 1_000_000
	supplyWhole     int64 = 100_000_000
	seasonWhole     int64 = 43_000_000
	liquidityWhole  int64 = 20_000_000
	ecosystemWhole  int64 = 15_000_000
	communityWhole  int64 = 12_000_000
	teamWhole       int64 = 10_000_000
	maxBuyTaxBps    int64 = 500
	maxSellTaxBps   int64 = 1000
	defaultBuyTax   int64 = 200
	defaultSellTax  int64 = 400
)

var (
	token     *grc20.Token
	ledger    *grc20.PrivateLedger
	admin     *ownable.Ownable
	inited     bool
	sealed     bool
	spender    address
	spenderSet bool
	buyTaxBps  int64 = defaultBuyTax
	sellTaxBps int64 = defaultSellTax
)

// Init mints the fixed supply once and seals the ledger. The five treasuries must be distinct.
func Init(cur realm, season, liquidity, ecosystem, community, team address) {
	if !cur.IsCurrent() {
		panic("shoaltoken: realm")
	}
	if !cur.Previous().IsUserCall() {
		panic("shoaltoken: eoa")
	}
	takeExact(0)
	if inited {
		panic("shoaltoken: init")
	}
	if !distinct(season, liquidity, ecosystem, community, team) {
		panic("shoaltoken: addr")
	}
	tok, led := grc20.NewToken("Shoal FISH", "FISH", 6, 0, cur)
	credit(led, season, seasonWhole*unit)
	credit(led, liquidity, liquidityWhole*unit)
	credit(led, ecosystem, ecosystemWhole*unit)
	credit(led, community, communityWhole*unit)
	credit(led, team, teamWhole*unit)
	if tok.TotalSupply() != supplyWhole*unit {
		panic("shoaltoken: supply")
	}
	token = tok
	ledger = led
	admin = ownable.NewWithAddress(cur.Previous().Address())
	inited = true
	sealed = true
	chain.Emit(
		"Init",
		"token", tok.ID(),
		"admin", cur.Previous().Address().String(),
		"supply", strconv.FormatInt(supplyWhole*unit, 10),
	)
}

// Transfer moves FISH from the caller to to. The amount is not taxed.
func Transfer(cur realm, to address, amount int64) {
	requireUser(cur)
	takeExact(0)
	requireReady()
	must(ledger.CallerTeller().Transfer(0, cur, to, amount))
	chain.Emit("Send", "to", to.String(), "amount", strconv.FormatInt(amount, 10))
}

// Approve lets spender move up to amount from the caller. This replaces the previous allowance.
func Approve(cur realm, spender address, amount int64) {
	requireUser(cur)
	takeExact(0)
	requireReady()
	must(ledger.CallerTeller().Approve(0, cur, spender, amount))
	chain.Emit("Approve", "spender", spender.String(), "amount", strconv.FormatInt(amount, 10))
}

// TransferFrom moves amount from owner to to, using the caller's allowance. The amount is not taxed.
func TransferFrom(cur realm, owner, to address, amount int64) {
	requireUser(cur)
	takeExact(0)
	requireReady()
	must(ledger.CallerTeller().TransferFrom(0, cur, owner, to, amount))
	chain.Emit("SendFrom", "owner", owner.String(), "to", to.String(), "amount", strconv.FormatInt(amount, 10))
}

// SetBuyTaxBps stores the buy tax for a later pool. The cap is 500 bps. This does not tax wallets.
func SetBuyTaxBps(cur realm, next int64) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	if !admin.OwnedBy(caller) {
		panic("shoaltoken: admin")
	}
	if next < 0 || next > maxBuyTaxBps {
		panic("shoaltoken: tax")
	}
	buyTaxBps = next
	chain.Emit("SetBuyTaxBps", "bps", strconv.FormatInt(next, 10))
}

// SetSellTaxBps stores the sell tax for a later pool. The cap is 1000 bps. This does not tax wallets.
func SetSellTaxBps(cur realm, next int64) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	if !admin.OwnedBy(caller) {
		panic("shoaltoken: admin")
	}
	if next < 0 || next > maxSellTaxBps {
		panic("shoaltoken: tax")
	}
	sellTaxBps = next
	chain.Emit("SetSellTaxBps", "bps", strconv.FormatInt(next, 10))
}

// TransferAdmin hands the tax hook to next. Balances stay where they are.
func TransferAdmin(cur realm, next address) {
	requireUser(cur)
	takeExact(0)
	requireReady()
	if !next.IsValid() {
		panic("shoaltoken: admin")
	}
	if err := admin.TransferOwnership(0, cur, next); err != nil {
		panic("shoaltoken: admin")
	}
	chain.Emit("TransferAdmin", "next", next.String())
}

func Name() string {
	requireReady()
	return token.GetName()
}

func Symbol() string {
	requireReady()
	return token.GetSymbol()
}

func Decimals() int {
	requireReady()
	return token.GetDecimals()
}

func TotalSupply() int64 {
	requireReady()
	return token.TotalSupply()
}

func BalanceOf(who address) int64 {
	requireReady()
	return token.BalanceOf(who)
}

func Allowance(owner, spender address) int64 {
	requireReady()
	return token.Allowance(owner, spender)
}

func TokenID() string {
	requireReady()
	return token.ID()
}

func BuyTaxBps() int64  { return buyTaxBps }
func SellTaxBps() int64 { return sellTaxBps }
func Version() string   { return "shoaltoken-1" }
func Sealed() bool      { return sealed }

// Spender is the one realm allowed to Draw. It is empty until SetSpender.
func Spender() address { return spender }

// SetSpender records the fish realm once. A later call cannot replace it.
func SetSpender(cur realm, who address) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	if !admin.OwnedBy(caller) {
		panic("shoaltoken: admin")
	}
	if spenderSet || !who.IsValid() {
		panic("shoaltoken: spender")
	}
	spender = who
	spenderSet = true
	chain.Emit("SetSpender", "who", who.String())
}

// Draw moves min(amount, balance, allowance) from owner to to.
// Only the recorded spender may call it. The owner must have approved that spender.
// A short balance or allowance moves nothing and does not panic. This does not mint.
func Draw(cur realm, owner, to address, amount int64) int64 {
	if !cur.IsCurrent() {
		panic("shoaltoken: realm")
	}
	if !spenderSet || cur.Previous().Address() != spender {
		panic("shoaltoken: spender")
	}
	takeExact(0)
	requireReady()
	if amount <= 0 || !owner.IsValid() || !to.IsValid() {
		return 0
	}
	bal := token.BalanceOf(owner)
	if amount > bal {
		amount = bal
	}
	allow := token.Allowance(owner, spender)
	if amount > allow {
		amount = allow
	}
	if amount <= 0 {
		return 0
	}
	must(ledger.CallerTeller().TransferFrom(0, cur, owner, to, amount))
	chain.Emit("Draw", "owner", owner.String(), "to", to.String(), "amount", strconv.FormatInt(amount, 10))
	return amount
}

func Admin() address {
	if admin == nil {
		return address("")
	}
	return admin.Owner()
}

func Render(path string) string {
	if path != "" {
		return "# Shoal FISH\n\nUnknown path.\n"
	}
	return "# Shoal FISH\n\nFixed supply. Wallet transfers are not taxed.\n\nThe symbol FISH shares its letters with the fish NFT collection. TokenID is the chain identity.\n"
}

func credit(led *grc20.PrivateLedger, who address, amount int64) {
	if err := led.Mint(who, amount); err != nil {
		panic(err)
	}
}

func must(err error) {
	if err != nil {
		panic(err)
	}
}

func requireReady() {
	if !inited || !sealed || token == nil || ledger == nil || admin == nil {
		panic("shoaltoken: init")
	}
}

func requireUser(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("shoaltoken: eoa")
	}
	return cur.Previous().Address()
}

func takeExact(n int64) {
	sent := unsafe.OriginSend()
	if n == 0 {
		if len(sent) != 0 {
			panic("shoaltoken: payment")
		}
		return
	}
	panic("shoaltoken: payment")
}

func distinct(xs ...address) bool {
	for i, a := range xs {
		if !a.IsValid() {
			return false
		}
		for j := 0; j < i; j++ {
			if xs[j] == a {
				return false
			}
		}
	}
	return true
}

package fish

import (
	"chain"
	"strconv"
)

func List(cur realm, id int, priceUgnot int64) {
	caller := requireUser(cur)
	if priceUgnot <= 0 || priceUgnot > maxPrice {
		panic("fish: price")
	}
	takeExact(0)
	body := must(id)
	if body.owner != caller {
		panic("fish: owner")
	}
	guardMovable(body)
	if body.mustHeal {
		panic("fish: heal")
	}
	moveToken(caller, caller, self, id)
	body.listed = true
	body.seller = caller
	body.price = priceUgnot
	body.owner = self
	chain.Emit("List", "id", strconv.Itoa(id), "seller", caller.String(), "price", strconv.FormatInt(priceUgnot, 10))
}

func UpdatePrice(cur realm, id int, priceUgnot int64) {
	caller := requireUser(cur)
	if priceUgnot <= 0 || priceUgnot > maxPrice {
		panic("fish: price")
	}
	takeExact(0)
	body := must(id)
	if !body.listed {
		panic("fish: listed")
	}
	if body.seller != caller {
		panic("fish: owner")
	}
	body.price = priceUgnot
	chain.Emit("List", "id", strconv.Itoa(id), "seller", caller.String(), "price", strconv.FormatInt(priceUgnot, 10))
}

func Cancel(cur realm, id int) {
	caller := requireUser(cur)
	takeExact(0)
	body := must(id)
	if !body.listed {
		panic("fish: listed")
	}
	if body.seller != caller {
		panic("fish: owner")
	}
	moveToken(self, self, body.seller, id)
	body.owner = body.seller
	body.seller = address("")
	body.price = 0
	body.listed = false
	chain.Emit("Cancel", "id", strconv.Itoa(id))
}

func Buy(cur realm, id int) {
	caller := requireUser(cur)
	body := must(id)
	if !body.listed {
		panic("fish: listed")
	}
	if caller == body.seller {
		panic("fish: self")
	}
	takeExact(body.price)
	proto := body.price * protocolBps / 10000
	royal := body.price * royaltyBps / 10000
	if proto+royal > body.price {
		panic("fish: fee")
	}
	sellerAmt := body.price - proto - royal
	send(body.seller, sellerAmt, cur)
	send(creator, royal, cur)
	send(protocolSink, proto, cur)
	moveToken(self, self, caller, id)
	body.owner = caller
	body.seller = address("")
	body.price = 0
	body.listed = false
	chain.Emit("Buy", "id", strconv.Itoa(id), "buyer", caller.String())
}

func SellerOf(id int) address { return must(id).seller }
func PriceOf(id int) int64    { return must(id).price }
func ImageOf(id int) string   { return must(id).image }
func NameOf(id int) string    { return must(id).name }

func GrcOwnerOf(id int) string {
	who, err := OwnerOf(strconv.Itoa(id))
	if err != nil {
		return ""
	}
	return who.String()
}

func ItemLine(id int) string {
	body := must(id)
	return strconv.Itoa(body.id) + "|" + body.name + "|" + addrStr(body.owner) + "|" + addrStr(body.seller) + "|" +
		strconv.FormatInt(body.price, 10) + "|" + strconv.FormatBool(body.listed) + "|" + body.image + "|fish|" +
		body.rarity + "|Size:" + body.size + ";Trait:" + body.trait + ";Species:" + body.species + ";HP:" + strconv.Itoa(body.hp) +
		"|true|-1"
}

func ListOpen() string {
	requireInit()
	out := ""
	n := 0
	for _, body := range bodies {
		if body == nil || !body.listed || body.burned {
			continue
		}
		if n >= listCap {
			break
		}
		if out != "" {
			out += "\n"
		}
		out += ItemLine(body.id)
		n++
	}
	return out
}

func addrStr(a address) string {
	if !a.IsValid() {
		return ""
	}
	return a.String()
}

package fish

import (
	"chain"
	"strconv"
	"time"

	"gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/shoal/party"
	"gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/shoal/shoaltoken"
)

type damageRow struct {
	owner address
	dmg   int
}

// blows[victimID] sums HP actually removed, keyed by the attacker's owner.
var blows [][]damageRow

// Bite is one user call and takes no payment. The hit test is sector-center
// reach plus a 42 degree mouth cone. A miss does not start cooldown. Members
// of the same party cannot bite each other. A killing blow pays the smaller
// Pool X and leaves the NFT at 30% HP. The killer share is split by HP removed.
// Empty cheer pays the team sink. A new kill does not drop watch shards.
// Buyback GNOT that cannot buy one FISH from the reserve burns. Spent GNOT joins liquidity.
func Bite(cur realm, id, target int) {
	caller := requireUser(cur)
	takeExact(0)
	if id == target {
		panic("fish: bite")
	}
	atk := must(id)
	vic := must(target)
	if atk.owner != caller {
		panic("fish: owner")
	}
	if atk.mustHeal || vic.mustHeal {
		panic("fish: heal")
	}
	now := time.Now().Unix()
	if !liveFish(atk, now) || !liveFish(vic, now) {
		panic("fish: match")
	}
	if atk.owner == vic.owner {
		panic("fish: bite")
	}
	if party.SameParty(cross(cur), atk.owner, vic.owner) {
		panic("fish: party")
	}
	nowMs := time.Now().UnixMilli()
	// A cave or reef does not dodge. The cone still has to face the fish inside.
	if !mouthHit(atk, vic) && !shelterMouth(atk, vic, nowMs) {
		panic("fish: range")
	}
	if nowMs < atk.nextBiteMilli {
		panic("fish: cool")
	}
	if atk.bittenBy == vic.id && nowMs < atk.bittenUntil {
		panic("fish: cool")
	}
	cool := nowMs + cooldownMs(atk.rarity)
	atk.nextBiteMilli = cool
	atk.lastCombatMilli = nowMs
	if redirectShelter(atk, vic, nowMs) {
		chain.Emit("Bite", "id", strconv.Itoa(id), "target", strconv.Itoa(target), "damage", "shelter")
		return
	}
	vic.lastCombatMilli = nowMs
	vic.bittenBy = atk.id
	vic.bittenUntil = cool
	dmg := strikeFought(biteNow(atk), vic.hp, atk.size, vic.size, atk.rarity, vic.rarity)
	landed := dmg
	if landed > vic.hpNow {
		landed = vic.hpNow
	}
	addDamage(vic.id, atk.owner, landed)
	if vic.hpNow > dmg {
		vic.hpNow -= dmg
		chain.Emit("Bite", "id", strconv.Itoa(id), "target", strconv.Itoa(target), "damage", strconv.Itoa(dmg))
		return
	}
	payKill(atk, vic, cur)
}

func payKill(atk, vic *fishBody, rlm realm) {
	if !rlm.IsCurrent() {
		panic("fish: realm")
	}
	covered := coveredStake(atk.pool, vic.pool)
	excess := vic.pool - covered
	killer, lp, team, buyback, cheer := splitParts(covered)
	stake := atk.pool
	nowMs := time.Now().UnixMilli()
	creditBout(atk)
	creditBout(vic)
	growFromKill(atk, vic)
	returnCheers(vic, rlm)
	vic.pool = 0
	vic.inMatch = false
	vic.boutPaid = false
	vic.mustHeal = true
	vic.hpNow = downHP(vic.hp)
	cheerHeld := bookCheerClaims(atk, vic, cheer, nowMs)
	team += cheer - cheerHeld
	send(vic.owner, excess, rlm)
	payKiller(atk.owner, vic.id, killer, rlm)
	send(lpSink, lp, rlm)
	send(teamSink, team, rlm)
	spent := settleBuyback(buyback, rlm)
	send(lpSink, spent, rlm)
	send(burnSink, buyback-spent, rlm)
	payWinFish(atk.owner, stake, rlm)
	clearDamage(vic.id)
	chain.Emit(
		"Kill",
		"id", strconv.Itoa(atk.id),
		"target", strconv.Itoa(vic.id),
		"covered", strconv.FormatInt(covered, 10),
		"killer", strconv.FormatInt(killer, 10),
	)
}

// payKiller splits the killer share by HP removed among current members.
// The party realm holds no coins. A solo owner, or a party with no recorded
// damage, receives the whole share. Dust goes to the highest damage, and a
// tie prefers the owner who landed the blow.
func payKiller(owner address, victim int, amount int64, rlm realm) {
	if amount <= 0 {
		return
	}
	pid := party.PartyOf(cross(rlm), owner)
	if pid == 0 {
		send(owner, amount, rlm)
		return
	}
	n := party.MemberCount(cross(rlm), pid)
	if n <= 0 {
		send(owner, amount, rlm)
		return
	}
	owners := make([]address, n)
	weights := make([]int, n)
	total := 0
	for i := 0; i < n; i++ {
		who := party.MemberAt(cross(rlm), pid, i)
		owners[i] = who
		w := damageOf(victim, who)
		if w < 0 {
			w = 0
		}
		weights[i] = w
		total += w
	}
	if total <= 0 {
		send(owner, amount, rlm)
		return
	}
	shares := splitWeights(amount, weights, owner, owners)
	for i := range owners {
		send(owners[i], shares[i], rlm)
	}
}

func splitWeights(amount int64, weights []int, prefer address, owners []address) []int64 {
	total := 0
	for _, w := range weights {
		if w > 0 {
			total += w
		}
	}
	out := make([]int64, len(weights))
	if amount <= 0 || total <= 0 {
		return out
	}
	var used int64
	best := -1
	bestW := 0
	for i, w := range weights {
		if w <= 0 {
			continue
		}
		share := amount * int64(w) / int64(total)
		out[i] = share
		used += share
		if best < 0 || w > bestW || (w == bestW && i < len(owners) && owners[i] == prefer) {
			best = i
			bestW = w
		}
	}
	if used < amount && best >= 0 {
		out[best] += amount - used
	}
	return out
}

func addDamage(id int, owner address, n int) {
	if n <= 0 || id < 1 || !owner.IsValid() {
		return
	}
	for len(blows) <= id {
		blows = append(blows, nil)
	}
	rows := blows[id]
	for i := 0; i < len(rows); i++ {
		if rows[i].owner == owner {
			rows[i].dmg += n
			blows[id] = rows
			return
		}
	}
	blows[id] = append(rows, damageRow{owner: owner, dmg: n})
}

func damageOf(id int, owner address) int {
	if id < 0 || id >= len(blows) {
		return 0
	}
	for i := 0; i < len(blows[id]); i++ {
		if blows[id][i].owner == owner && blows[id][i].dmg > 0 {
			return blows[id][i].dmg
		}
	}
	return 0
}

// clearDamage drops incoming blows so the next entry starts clean.
func clearDamage(id int) {
	if id < 0 || id >= len(blows) {
		return
	}
	blows[id] = nil
}

// creditBout counts one finished entry. Leave does not call it.
// SettleMatch does not count the entry again.
func creditBout(body *fishBody) {
	if body.boutPaid {
		return
	}
	body.boutPaid = true
	body.bouts++
}

func liveFish(body *fishBody, now int64) bool {
	if now < 0 {
		return false
	}
	return body.inMatch && body.pool > 0
}

func downHP(max int) int {
	hp := max * 30 / 100
	if hp < 1 {
		return 1
	}
	return hp
}

func coveredStake(killerPool, victimPool int64) int64 {
	if killerPool < 0 {
		killerPool = 0
	}
	if victimPool < 0 {
		victimPool = 0
	}
	if killerPool < victimPool {
		return killerPool
	}
	return victimPool
}

// splitParts is 80/10/3/3/4. Killer, liquidity, team, FISH buyback, cheer.
// Dust joins the buyback.
func splitParts(amount int64) (killer, lp, team, buyback, cheer int64) {
	if amount < 0 {
		amount = 0
	}
	killer = amount * 8000 / 10000
	lp = amount * 1000 / 10000
	team = amount * 300 / 10000
	buyback = amount * 300 / 10000
	cheer = amount * 400 / 10000
	dust := amount - killer - lp - team - buyback - cheer
	buyback += dust
	return
}

// settleBuyback spends whole FISH from the reserve at 0.02 GNOT each.
// GNOT that cannot buy one FISH stays with the caller to burn. This does not mint.
func settleBuyback(budget int64, rlm realm) int64 {
	if !rlm.IsCurrent() {
		panic("fish: realm")
	}
	units := reserveUnits(budget / twapUgnot)
	if units <= 0 {
		return 0
	}
	got := shoaltoken.Draw(cross(rlm), fishReserve, burnSink, units)
	if got != units {
		panic("fish: fish")
	}
	return (units / fishUnit) * twapUgnot
}

// payWinFish pays 1 whole FISH per 1 whole GNOT of the winner stake, then the party bonus.
// Both come from the reserve after buyback. A short reserve pays less. This does not mint.
func payWinFish(owner address, stake int64, rlm realm) {
	if !rlm.IsCurrent() {
		panic("fish: realm")
	}
	whole := stake / ugnot
	if whole < 0 {
		whole = 0
	}
	baseUnits := reserveUnits(whole)
	if baseUnits > 0 {
		got := shoaltoken.Draw(cross(rlm), fishReserve, owner, baseUnits)
		if got != baseUnits {
			panic("fish: fish")
		}
	}
	baseFish := baseUnits / fishUnit
	owners := partyMembers(owner, rlm)
	members := len(owners)
	if members == 0 {
		members = 1
	}
	bonusFish := baseFish * int64(partyFishBonusBps(members)) / 10000
	bonusUnits := reserveUnits(bonusFish)
	if bonusUnits <= 0 {
		return
	}
	shares := splitPartyFish(bonusUnits/fishUnit, owners, owner)
	for i := range owners {
		part := shares[i] * fishUnit
		if part <= 0 {
			continue
		}
		got := shoaltoken.Draw(cross(rlm), fishReserve, owners[i], part)
		if got != part {
			panic("fish: fish")
		}
	}
}

func reserveUnits(whole int64) int64 {
	if whole <= 0 || !fishTokenReady() || !fishReserve.IsValid() {
		return 0
	}
	units := whole * fishUnit
	room := shoaltoken.BalanceOf(fishReserve)
	allow := shoaltoken.Allowance(fishReserve, self)
	if allow < room {
		room = allow
	}
	room = room / fishUnit * fishUnit
	if units > room {
		return room
	}
	return units
}

func partyMembers(owner address, rlm realm) []address {
	pid := party.PartyOf(cross(rlm), owner)
	if pid == 0 {
		return nil
	}
	n := party.MemberCount(cross(rlm), pid)
	out := make([]address, n)
	for i := 0; i < n; i++ {
		out[i] = party.MemberAt(cross(rlm), pid, i)
	}
	return out
}

func partyFishBonusBps(members int) int {
	if members <= 1 {
		return 0
	}
	n := members
	if n > 8 {
		n = 8
	}
	return (n - 1) * 1000 / 7
}

func splitPartyFish(bonus int64, owners []address, killer address) []int64 {
	out := make([]int64, len(owners))
	if bonus <= 0 || len(owners) == 0 {
		return out
	}
	each := bonus / int64(len(owners))
	dustAt := 0
	for i, who := range owners {
		out[i] = each
		if who == killer {
			dustAt = i
		}
	}
	out[dustAt] += bonus - each*int64(len(owners))
	return out
}

func strikeDamage(bite, hpMax int, atkSize, defSize string) int {
	dmg := bite * 100 / (hpMax + 100)
	if dmg < 1 {
		dmg = 1
	}
	if sizeIndex(atkSize)-sizeIndex(defSize) >= 2 {
		dmg = dmg * 5000 / 10000
		if dmg < 1 {
			dmg = 1
		}
	}
	return dmg
}

func sizeIndex(size string) int {
	switch size {
	case "small":
		return 0
	case "medium":
		return 1
	case "large":
		return 2
	default:
		panic("fish: size")
	}
}

func biteOf(rarity, size, trait string) int {
	var base int64
	switch rarity {
	case "common":
		base = 22
	case "uncommon":
		base = 26
	case "rare":
		base = 31
	case "epic":
		base = 37
	case "legendary":
		base = 44
	case "mythic":
		base = 52
	default:
		panic("fish: rarity")
	}
	traitBps := int64(10000)
	if trait == "fang" {
		traitBps = 11200
	}
	sizeBps := int64(10000)
	if size == "small" {
		sizeBps = 8600
	} else if size == "large" {
		sizeBps = 11800
	}
	v := (base*traitBps*sizeBps + 50_000_000) / 100_000_000
	if v < 1 {
		v = 1
	}
	return int(v)
}

func cooldownMs(rarity string) int64 {
	switch rarity {
	case "common":
		return 2400
	case "uncommon":
		return 2550
	case "rare":
		return 2700
	case "epic":
		return 2850
	case "legendary":
		return 3000
	case "mythic":
		return 3200
	default:
		panic("fish: rarity")
	}
}

// reachUnits is the dodged bite reach in 1/10000 of a world unit.
// A sector is 8 world units, so the next center is 80000 units away.
func reachUnits(rarity, size string, dodgeTenths int) int64 {
	var spec int64
	switch rarity {
	case "common":
		spec = 10000
	case "uncommon":
		spec = 10600
	case "rare":
		spec = 11200
	case "epic":
		spec = 11800
	case "legendary":
		spec = 12400
	case "mythic":
		spec = 13200
	default:
		panic("fish: rarity")
	}
	sizeMod := int64(10000)
	if size == "small" {
		sizeMod = 8600
	} else if size == "large" {
		sizeMod = 12200
	}
	reach := spec * sizeMod * 8 / 10000
	reach -= int64(dodgeTenths) * 1000
	if reach < 10_000 {
		return 10_000
	}
	return reach
}

func inReach(atk, def *fishBody) bool {
	return inReachDodge(atk, def, def.dodge)
}

func inReachDodge(atk, def *fishBody, dodge int) bool {
	dx := int64(atk.sx - def.sx)
	dz := int64(atk.sz - def.sz)
	span := dx*dx + dz*dz
	reach := reachUnits(atk.rarity, atk.size, dodge)
	dist2 := span * 80_000 * 80_000
	return dist2 <= reach*reach
}

