func TokensOf(owner string) string {
	requireInit()
	who := address(owner)
	if !who.IsValid() {
		return ""
	}
	out := ""
	for _, body := range bodies {
		if body == nil || body.burned || body.owner != who {
			continue
		}
		if out != "" {
			out += ","
		}
		out += strconv.Itoa(body.id)
	}
	return out
}

func TokenOfOwnerByIndex(owner string, index int64) string {
	requireInit()
	who := address(owner)
	if !who.IsValid() {
		panic("fish: addr")
	}
	if index < 0 {
		panic("fish: index")
	}
	var seen int64
	for _, body := range bodies {
		if body == nil || body.burned || body.owner != who {
			continue
		}
		if seen == index {
			return strconv.Itoa(body.id)
		}
		seen++
	}
	panic("fish: index")
}

